// ════════════════════════════════════════════════════════════════════════════
// StarSeed OS — Protomolécula · Catálogo de herramientas (datos puros)
// ----------------------------------------------------------------------------
// Qué es: la lista VERIFICADA de las herramientas de creación y edición que la
// Protomolécula puede ofrecer como átomos de una molécula: las apps de ArtCraft
// (getartcraft.com; ojo, «getarcraft.com» no existe) y lo mejor de código
// abierto de fuera. Doc: `architecture/protomolecula-catalogo.md`.
//
// Cómo leerlo (honestidad radical, regla de la casa):
//   · `estado` NO dice «ya corre en el OS»: dice si esta herramienta PUEDE entrar
//     y por qué vía (`integracion`). «integrable» = licencia que lo permite y
//     vía técnica comprobada; falta que el OS escriba el átomo.
//   · «proximamente» = hay camino pero falta una pieza externa; `motivo` dice cuál.
//   · «solo-enlace» = no se puede incorporar (licencia o condiciones); `motivo`.
//   · GPL/AGPL: solo como programa APARTE (nunca enlazada ni en el mismo
//     proceso del OS). El código ajeno jamás se ejecuta en el hilo del OS:
//     editable sí, ejecutable no.
//   · Los modelos de IA tienen DOS licencias: `licencia` (código) y
//     `licenciaPesos` (pesos). Manda la más restrictiva.
//   · `verificado`: día en que se comprobó licencia y versión contra el origen.
//     `sinComprobar` lista lo que NO se pudo contrastar.
//
// Módulo PURO: sin red, sin disco, sin `node:*`, sin React. Importable desde el
// cliente. Las versiones (`actualizacion.ultimaVersion`) las mantiene al día
// `scripts/protomolecula/actualizar_catalogo.py`, que solo reescribe esas líneas.
// La línea `actualizacion: {…}` de cada entrada va SIEMPRE en una sola línea.
// ════════════════════════════════════════════════════════════════════════════

