export const IDS_GRUPO_PROTO = [
  "imagen",
  "documentos",
  "audio",
  "video",
  "3d",
  "arquitectura",
  "fisicas",
  "juegos",
  "vr-ar",
  "codigo",
  "ia",
  "controles",
  "colaboracion",
  "recursos",
] as const;
/** Agrupación de la Biblioteca (las diez del contrato más cuatro propias). */
export type GrupoProto = (typeof IDS_GRUPO_PROTO)[number];

/** `arcraft` = de getartcraft.com · `github` = repositorio abierto · `otro` = estándar, servicio o fuente fuera de GitHub. */
export type OrigenProto = "arcraft" | "github" | "otro";

/** Los tres grados + sus variantes del contrato (`architecture/protomolecula.md` §3.2). */
export type IntegracionProto =
  | "iframe-aislado"
  | "wasm-en-worker"
  | "libreria-js"
  | "app-nativa-puente"
  | "servicio-local"
  | "servidor-remoto"
  | "solo-enlace";

export type EstadoProto = "integrable" | "proximamente" | "solo-enlace";

/** De dónde sale la última versión. `web` = sin consulta automática (se mira a mano). */
export type FuenteVersionProto = "github-releases" | "github-tags" | "npm" | "pypi" | "flathub" | "web";

/** app = se usa tal cual · libreria = se importa · modelo = pesos + código · estandar = API del navegador o protocolo · servicio = nube de terceros · recurso = biblioteca de assets. */
export type TipoProto = "app" | "libreria" | "modelo" | "estandar" | "servicio" | "recurso";

export const VIAS_CONTROL_PROTO = [
  "cli",
  "http",
  "intents",
  "js",
  "json-lineas",
  "lua",
  "mcp",
  "midi",
  "ninguno",
  "osc",
  "postMessage",
  "python",
  "tuberia",
  "websocket",
] as const;
export type ViaControlProto = (typeof VIAS_CONTROL_PROTO)[number];

/** Qué se puede hacer con la licencia según la regla de la casa. */
export type UsoLicencia =
  | "enlazable" // permisiva: se puede importar en el paquete
  | "enlazable-con-aviso" // LGPL/MPL: separable y reemplazable
  | "programa-aparte" // GPL/AGPL: solo como programa o servidor aparte
  | "estandar" // especificación abierta (W3C, Bluetooth…), no es código nuestro
  | "sin-permiso"; // propietaria, no comercial o con restricciones: solo enlace

export interface MediosProto {
  /** `embebible` = iframe/librería · `wasm` = build WebAssembly · `no` = no corre en el navegador. */
  web: "embebible" | "wasm" | "no";
  android: boolean;
  ios: boolean;
  macos: boolean;
  windows: boolean;
  linux: boolean;
  /** Corre sin pantalla en un servidor o una neurona de escritorio. */
  servidor: boolean;
}

export interface ActualizacionProto {
  fuente: FuenteVersionProto;
  /** `owner/repo` (GitHub), nombre del paquete (npm/PyPI), id de Flathub, o una URL (web). */
  ref: string;
  ultimaVersion: string | null;
  /** AAAA-MM-DD */
  fechaVersion: string | null;
  /** Expresión regular sobre la etiqueta, cuando la última «latest» de GitHub no es la estable. */
  filtro?: string;
}

export interface HerramientaProto {
  /** kebab-case, único y estable. */
  id: string;
  nombre: string;
  categoria: CategoriaProto;
  tipo: TipoProto;
  origen: OrigenProto;
  descripcion: string;
  /** Licencia del CÓDIGO, id SPDX (o `LicenseRef-…` / `NOASSERTION`). */
  licencia: string;
  /** Licencia de los PESOS del modelo, si es un modelo y es distinta. */
  licenciaPesos?: string;
  /** Repositorio verificado, o null si no hay (estándares y servicios). Nunca inventado. */
  codigo: string | null;
  web: string | null;
  medios: MediosProto;
  integracion: IntegracionProto;
  formatos: { entrada: readonly string[]; salida: readonly string[] };
  control: { via: readonly ViaControlProto[]; notas: string };
  actualizacion: ActualizacionProto;
  /** Qué pueden hacer con ella las IA y los agentes (etiquetas libres). */
  ia: readonly string[];
  estado: EstadoProto;
  /** Por qué el estado es el que es y cómo entra. Obligatorio. */
  motivo: string;
  /** AAAA-MM-DD */
  verificado: string;
  /** Datos que NO se pudieron contrastar en la verificación. */
  sinComprobar?: readonly string[];
  /** Avisos de licencia, marca, estabilidad o privacidad. */
  avisos?: readonly string[];
}

export interface CategoriaInfo {
  id: CategoriaProto;
  grupo: GrupoProto;
  nombre: string;
  descripcion: string;
  /** Nombre de icono lucide (la Biblioteca lo resuelve con respaldo). */
  icono: string;
}

export interface GrupoInfo {
  id: GrupoProto;
  nombre: string;
  descripcion: string;
}

