/* ─────────────────────── Licencias: qué se puede hacer ─────────────────────── */

const RANGO_USO: Record<UsoLicencia, number> = {
  enlazable: 0,
  estandar: 0,
  "enlazable-con-aviso": 1,
  "programa-aparte": 2,
  "sin-permiso": 3,
};

function usoDeUnaLicencia(id: string): UsoLicencia {
  const l = id.trim().replace(/^\(|\)$/g, "");
  if (/^(A?GPL)(-|$)/.test(l)) return "programa-aparte";
  if (/^(LGPL|MPL|EPL|CDDL)(-|$)/.test(l)) return "enlazable-con-aviso";
  if (/^(MIT|Apache-2\.0|BSD-[23]-Clause|ISC|Zlib|CC0-1\.0|Unlicense|0BSD|BlueOak-1\.0\.0)$/.test(l)) return "enlazable";
  return "sin-permiso";
}

/**
 * Qué permite la licencia de una herramienta. `A OR B` = la persona elige la más
 * permisiva; `A AND B` = obliga la más restrictiva. Si es un estándar abierto
 * no es código nuestro. Todo lo desconocido (`LicenseRef-…`, `NOASSERTION`) es
 * «sin-permiso»: el catálogo prefiere pecar de prudente.
 */
export function usoLicencia(h: Pick<HerramientaProto, "licencia" | "tipo">): UsoLicencia {
  if (h.tipo === "estandar") return "estandar";
  const alternativas = h.licencia.split(/\s+OR\s+/).map((alt) => {
    const partes = alt.split(/\s+AND\s+/).map(usoDeUnaLicencia);
    return partes.reduce((a, b) => (RANGO_USO[b] > RANGO_USO[a] ? b : a));
  });
  return alternativas.reduce((a, b) => (RANGO_USO[b] < RANGO_USO[a] ? b : a));
}

/** Integraciones que ejecutan el código dentro del proceso del OS (enlazan). */
const ENLAZAN: readonly IntegracionProto[] = ["libreria-js", "wasm-en-worker"];

/** Regla de la casa: una herramienta GPL/AGPL nunca puede integrarse enlazada. */
export function respetaReglaDeLicencia(h: HerramientaProto): boolean {
  const uso = usoLicencia(h);
  if (uso === "programa-aparte") return !ENLAZAN.includes(h.integracion);
  if (uso === "sin-permiso") return h.estado !== "integrable";
  return true;
}

/* ─────────────────────────── Consultas puras ─────────────────────────── */

function sinTildes(t: string): string {
  return t.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
}

export function herramientaPorId(id: string, catalogo: readonly HerramientaProto[] = CATALOGO_PROTOMOLECULA): HerramientaProto | undefined {
  return catalogo.find((h) => h.id === id);
}

export function porCategoria(categoria: CategoriaProto, catalogo?: readonly HerramientaProto[]): HerramientaProto[];
export function porCategoria(): Record<CategoriaProto, HerramientaProto[]>;
/** Las herramientas de una categoría; sin argumentos, todas agrupadas por categoría. */
export function porCategoria(
  categoria?: CategoriaProto,
  catalogo: readonly HerramientaProto[] = CATALOGO_PROTOMOLECULA,
): HerramientaProto[] | Record<CategoriaProto, HerramientaProto[]> {
  if (categoria) return catalogo.filter((h) => h.categoria === categoria);
  const todas = {} as Record<CategoriaProto, HerramientaProto[]>;
  for (const c of IDS_CATEGORIA_PROTO) todas[c] = [];
  for (const h of catalogo) todas[h.categoria].push(h);
  return todas;
}

/**
 * Busca por palabras (sin mayúsculas ni tildes; todas deben aparecer) en nombre,
 * id, descripción, categoría, licencia, formatos y capacidades de IA. Primero
 * las que casan en el nombre.
 */
export function buscar(texto: string, catalogo: readonly HerramientaProto[] = CATALOGO_PROTOMOLECULA): HerramientaProto[] {
  const palabras = sinTildes(texto).split(/\s+/).filter(Boolean);
  if (palabras.length === 0) return [];
  const nombreCat = new Map(CATEGORIAS_PROTOMOLECULA.map((c) => [c.id, c.nombre] as const));
  const puntuadas: Array<{ h: HerramientaProto; puntos: number }> = [];
  for (const h of catalogo) {
    const nombre = sinTildes(h.nombre);
    const id = h.id;
    const resto = sinTildes(
      [h.descripcion, h.categoria, nombreCat.get(h.categoria) ?? "", h.licencia, h.licenciaPesos ?? "", h.formatos.entrada.join(" "), h.formatos.salida.join(" "), h.ia.join(" "), h.tipo].join(" "),
    );
    let puntos = 0;
    let todas = true;
    for (const p of palabras) {
      if (nombre.includes(p)) puntos += 3;
      else if (id.includes(p)) puntos += 2;
      else if (resto.includes(p)) puntos += 1;
      else {
        todas = false;
        break;
      }
    }
    if (todas) puntuadas.push({ h, puntos });
  }
  puntuadas.sort((a, b) => b.puntos - a.puntos || a.h.nombre.localeCompare(b.h.nombre, "es"));
  return puntuadas.map((x) => x.h);
}

export interface ResumenCatalogo {
  total: number;
  porEstado: Record<EstadoProto, number>;
  porOrigen: Record<OrigenProto, number>;
  porCategoria: Record<CategoriaProto, number>;
  /** Apps de ArtCraft (las que enseña getartcraft.com/apps). */
  appsArcraft: number;
  appsArcraftCodigoAbierto: number;
  /** Fuera de ArtCraft. */
  herramientasFuera: number;
}

/** Ids de las siete Craft Apps de getartcraft.com/apps (verificado 2026-10-10). */
export const IDS_APPS_ARCRAFT = [
  "photocraft",
  "vectorcraft",
  "filmcraft",
  "lightcraft",
  "pdfcraft",
  "effectcraft",
  "designcraft",
] as const;

export function resumenCatalogo(catalogo: readonly HerramientaProto[] = CATALOGO_PROTOMOLECULA): ResumenCatalogo {
  const r: ResumenCatalogo = {
    total: catalogo.length,
    porEstado: { integrable: 0, proximamente: 0, "solo-enlace": 0 },
    porOrigen: { arcraft: 0, github: 0, otro: 0 },
    porCategoria: {} as Record<CategoriaProto, number>,
    appsArcraft: 0,
    appsArcraftCodigoAbierto: 0,
    herramientasFuera: 0,
  };
  for (const c of IDS_CATEGORIA_PROTO) r.porCategoria[c] = 0;
  const apps = new Set<string>(IDS_APPS_ARCRAFT);
  for (const h of catalogo) {
    r.porEstado[h.estado] += 1;
    r.porOrigen[h.origen] += 1;
    r.porCategoria[h.categoria] += 1;
    if (apps.has(h.id)) {
      r.appsArcraft += 1;
      if (usoLicencia(h) !== "sin-permiso") r.appsArcraftCodigoAbierto += 1;
    }
    if (h.origen !== "arcraft") r.herramientasFuera += 1;
  }
  return r;
}

/* ───────────────────────── Puente a la Biblioteca ───────────────────────── */

const RE_GITHUB = /^https:\/\/github\.com\/([^/\s]+\/[^/\s]+?)(?:\/.*)?$/;
const RE_HF = /^https:\/\/huggingface\.co\/[^/\s]+\/[^/\s]+/;

/** `owner/repo` de una URL de GitHub, o null. */
export function repoDeGithub(url: string | null): string | null {
  if (!url) return null;
  const m = RE_GITHUB.exec(url);
  return m ? m[1].replace(/\.git$/, "") : null;
}

function autorDe(h: HerramientaProto): string {
  if (h.origen === "arcraft") return "ArtCraft (storytold)";
  const m = /^https:\/\/(?:github\.com|codeberg\.org|framagit\.org|invent\.kde\.org|gitlab\.com)\/([^/\s]+)/.exec(h.codigo ?? "");
  if (m) return m[1];
  return h.tipo === "estandar" ? "Estándar abierto" : "Comunidad";
}

/**
 * Convierte una herramienta en un paquete de la Biblioteca (`kind` «app» o «repo»).
 * Sin `route`: instalar = guardar el enlace y abrirlo (semántica «externo» de
 * `packages.ts`); nada se promete de lo que no corre. `comingSoon` si no es
 * «integrable». `payload.upstream` solo para GitHub o Hugging Face, que son
 * los que entiende `/api/library/actualizaciones` (versión = sha corto).
 */
export function aPaqueteBiblioteca(h: HerramientaProto): LibraryPackage {
  const categoria = CATEGORIAS_PROTOMOLECULA.find((c) => c.id === h.categoria);
  const githubRepo = repoDeGithub(h.codigo);
  const upstream = githubRepo ? (h.codigo as string) : h.web && RE_HF.test(h.web) ? h.web : undefined;
  const proximamente = h.estado !== "integrable";
  const payload: Record<string, unknown> = {
    externalUrl: h.web ?? h.codigo ?? "",
    categoria: h.categoria,
    grupo: categoria?.grupo,
    protomolecula: {
      id: h.id,
      integracion: h.integracion,
      estado: h.estado,
      licencia: h.licencia,
      licenciaPesos: h.licenciaPesos,
      uso: usoLicencia(h),
      fuenteVersion: h.actualizacion.fuente,
      fechaVersion: h.actualizacion.fechaVersion,
      verificado: h.verificado,
    },
    motivo: h.motivo,
  };
  if (githubRepo) payload.githubRepo = githubRepo;
  if (upstream) payload.upstream = upstream;
  return {
    id: `proto-${h.id}`,
    kind: h.tipo === "app" ? "app" : "repo",
    name: h.nombre,
    description: proximamente ? `${h.descripcion} Próximamente: ${h.motivo}` : h.descripcion,
    icon: categoria?.icono ?? "Package",
    tags: ["protomolecula", h.categoria, h.integracion, h.licencia, h.tipo, h.estado],
    version: h.actualizacion.ultimaVersion ?? "sin versión comprobada",
    author: autorDe(h),
    sourceRepoId: "protomolecula",
    free: true,
    comingSoon: proximamente,
    payload,
  };
}
